body.t-bauhaus .bg-fx {
  background:
    radial-gradient(circle 150px at 88% 14%, #d64541 98%, transparent),
    linear-gradient(45deg, transparent 49.7%, #f2b705 50%, transparent 50.3%),
    radial-gradient(circle 90px at 6% 88%, #1f5fa8 98%, transparent),
    linear-gradient(#f2b705, #f2b705);
  background-size: 300px 300px, 180px 180px, 180px 180px, 90px 90px;
  background-position: 88% 5%, 4% 30%, 3% 88%, 82% 80%;
  background-repeat: no-repeat;
  opacity: .9;
}
body.t-bauhaus nav { border-bottom-width: 4px; }
body.t-bauhaus .logo span { background: #d64541; color: #f2ede4; padding: 0 6px; margin-left: 4px; border-radius: 50%; }
body.t-bauhaus .hero h1 { font-weight: 900; }
body.t-bauhaus .hero h1::after { content: ""; display: block; width: 90px; height: 45px; margin-top: 10px; background: #f2b705; border-radius: 90px 90px 0 0; }
body.t-bauhaus .tagline { color: #1f5fa8; text-transform: uppercase; letter-spacing: 3px; }
body.t-bauhaus .section-title::before { content: ""; display: inline-block; width: 20px; height: 20px; background: #d64541; border-radius: 50%; margin-right: 14px; vertical-align: baseline; }
body.t-bauhaus .section-tag { background: #141414; color: #f2ede4; border-color: #141414; font-weight: 700; letter-spacing: 3px; }
body.t-bauhaus .card { border-width: 2px; border-top-width: 10px; }
body.t-bauhaus .card:nth-child(3n+1) { border-top-color: #d64541; }
body.t-bauhaus .card:nth-child(3n+2) { border-top-color: #f2b705; }
body.t-bauhaus .card:nth-child(3n) { border-top-color: #1f5fa8; }
body.t-bauhaus .card:hover { border-color: #141414; box-shadow: 8px 8px 0 rgba(20,20,20,.12); }
